import re

def _parse_to_version_info(version_string):
    match = re.match(r'(\d+)\.(\d+)\.(\d+)', version_string)
    if not match:
        raise ValueError(f'Invalid version string: {version_string}')

    major, minor, micro = int(match.group(1)), int(match.group(2)), int(match.group(3))

    releaselevel = 'final'
    serial = 0

    remainder = version_string[match.end():]

    if remainder:
        dev_match = re.search(r'\.dev(\d+)', remainder)
        if dev_match:
            releaselevel = 'alpha'
            serial = int(dev_match.group(1))
        else:
            post_match = re.search(r'\.post(\d+)', remainder)
            if post_match:
                releaselevel = 'alpha'
                serial = int(post_match.group(1))
                micro += 1
            else:
                rc_match = re.search(r'rc(\d+)', remainder)
                if rc_match:
                    releaselevel = 'candidate'
                    serial = int(rc_match.group(1))

    return (major, minor, micro, releaselevel, serial)

# Test problematic cases
problematic_cases = [
    '3.5',  # Only major.minor
    'v3.5.0',  # Starts with v
    '3.5.0.0',  # 4-part version
    '3.5.0beta1',  # beta instead of rc
    '3.5.0-rc1',  # Hyphen instead of nothing
]

for version_str in problematic_cases:
    try:
        result = _parse_to_version_info(version_str)
        print(f'{version_str}: {result}')
    except Exception as e:
        print(f'{version_str}: ERROR - {type(e).__name__}: {e}')
EOF
